# -*- coding: utf-8 -*-
"""补丁2：为 15 家供应商生成股权穿透 / 幕后关系 / 项目管理的本地沉淀数据。"""
import io, os

P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data_srm_mock.py')
S = io.open(P, encoding='utf-8').read()
DONE = []


def once(old, new, tag):
    global S
    n = S.count(old)
    if n != 1:
        raise SystemExit('[%s] 期望 1 处，实际 %d 处' % (tag, n))
    S = S.replace(old, new)
    DONE.append(tag)



BLOCK = "# ==========================================================================\n# 4.1 15 家供应商图谱任务（页面5 股权穿透 / 页面6 幕后关系）\n#     语义：以下数据均为历史调用天眼查付费接口（821/1123/1156/1158/1160/1161）\n#     后回写并沉淀在本地的结果；本地命中即可直接回放，不再重复付费外调。\n# ==========================================================================\n_GEN_SUP = {r[0]: {'name': r[2], 'credit': r[3], 'tyc': r[5], 'legal': r[6],\n                   'cap': r[7], 'est': r[9], 'monitor': r[19]} for r in SUPPLIERS}\n_GEN_BY_NAME = {v['name']: k for k, v in _GEN_SUP.items()}\n_SH_BY = {}\nfor _r in SHAREHOLDERS:\n    _SH_BY.setdefault(_r[1], []).append(_r)\n_PE_BY = {}\nfor _r in PERSONS:\n    _PE_BY.setdefault(_r[1], []).append(_r)\n_TEL_OWNER, _MAIL_OWNER = {}, {}\nfor _s, _v in sorted(_tel.items()):\n    _TEL_OWNER.setdefault(_v, []).append(_s)\nfor _s, _v in sorted(_mail.items()):\n    _MAIL_OWNER.setdefault(_v, []).append(_s)\n\n_GEN_TASKS, _GEN_NODES, _GEN_EDGES = [], [], []\n_TS = '2026-11-18 15:00:00'\n_seq = {'n': 2301, 'e': 3301}\n\n\ndef _gn(task_id, key, ntype, name, credit, level, parent, can_extend, red, monitor,\n        supplier_id, group, api_id, attrs=None):\n    row = (_seq['n'], task_id, key, ntype, name, credit,\n           '存续' if ntype == 'Company' else None, level, parent, can_extend, red,\n           monitor, supplier_id, group, attrs or {}, {}, api_id, None, _TS)\n    _seq['n'] += 1\n    return row\n\n\ndef _ge(task_id, frm, to, rel, ratio, label, weight, rule_id, api_id):\n    row = (_seq['e'], task_id, 'E%d-%s-%s' % (task_id, frm, to), frm, to, frm, to, rel,\n           ratio, label, 'Y', weight, rule_id, None, api_id, None, _TS)\n    _seq['e'] += 1\n    return row\n\n\ndef _gtask(tid, tno, ttype, scene, sid, count, units):\n    sup = _GEN_SUP[sid]\n    return (tid, tno, 'MOCKTRACE-%d' % tid, ttype, scene, None, None, sup['credit'],\n            sup['name'], sup['name'], 'ALL', 'both', 4, 0.0000, 100.0000, 1, 1, '1',\n            'SUCCESS', 2, _TS, _TS, '1', units, 10.00, 'DONE', None, None, count,\n            _TS, _TS, 18600, 'prod', 'admin', _TS, _TS)\n\n\n# ---------- 页面5：股权穿透（向上股东 + 向下投资 + 主要人员） ----------\nfor _sid in sorted(_GEN_SUP):\n    _sup = _GEN_SUP[_sid]\n    _grp = 'GRP-%d' % _sid\n    _tid = 1300 + (_sid - 1000)\n    _nodes, _edges = [], []\n    _center = 'C%d' % _sid\n    _nodes.append(_gn(_tid, _center, 'Company', _sup['name'], _sup['credit'], 0, None,\n                      '1', '0', _sup['monitor'], _sid, _grp, 1160,\n                      {'position': '中心企业', 'ratioLabel': '起点'}))\n    _parent_companies = []\n    for _j, _sh in enumerate(_SH_BY.get(_sid, []), start=1):\n        _sname, _stype, _hcgid, _ratio = _sh[2], _sh[3], _sh[6], _sh[7]\n        _rtxt = '%g%%' % round(_ratio * 100, 4)\n        if _stype == '1' and _sname in _GEN_BY_NAME:\n            _other = _GEN_BY_NAME[_sname]\n            _key = 'C%d' % _other\n            if _key not in [n[2] for n in _nodes]:\n                _nodes.append(_gn(_tid, _key, 'Company', _sname, _GEN_SUP[_other]['credit'],\n                                  1, _center, '1', '0', _GEN_SUP[_other]['monitor'], _other,\n                                  _grp, 821, {'position': '股东企业', 'ratioLabel': _rtxt}))\n            _parent_companies.append((_other, _key))\n        else:\n            _key = 'H%d_%d' % (_sid, _j)\n            _nodes.append(_gn(_tid, _key, 'Human', _sname, None, 1, _center, '0',\n                              '1' if _hcgid else '0', '0', None, _grp, 1123,\n                              {'position': '自然人股东', 'ratioLabel': _rtxt}))\n        _edges.append(_ge(_tid, _key, _center, 'INVEST', _ratio, _rtxt, 5, 1, 821))\n    for _other, _pkey in _parent_companies:\n        for _sh in _SH_BY.get(_other, []):\n            _sname, _stype, _hcgid, _ratio = _sh[2], _sh[3], _sh[6], _sh[7]\n            _rtxt = '%g%%' % round(_ratio * 100, 4)\n            if _stype == '1' and _sname in _GEN_BY_NAME:\n                _o2 = _GEN_BY_NAME[_sname]\n                _k2 = 'C%d' % _o2\n                if _k2 in [n[2] for n in _nodes]:\n                    continue\n                _nodes.append(_gn(_tid, _k2, 'Company', _sname, _GEN_SUP[_o2]['credit'], 2,\n                                  _pkey, '1', '0', _GEN_SUP[_o2]['monitor'], _o2, _grp,\n                                  821, {'position': '间接股东企业', 'ratioLabel': _rtxt}))\n                _edges.append(_ge(_tid, _k2, _pkey, 'INVEST', _ratio, _rtxt, 5, 1, 821))\n            else:\n                _k2 = 'H%d_1' % _other\n                if _k2 in [n[2] for n in _nodes]:\n                    continue\n                _nodes.append(_gn(_tid, _k2, 'Human', _sname, None, 2, _pkey, '0',\n                                  '1' if _hcgid else '0', '0', None, _grp, 1123,\n                                  {'position': '间接自然人股东', 'ratioLabel': _rtxt}))\n                _edges.append(_ge(_tid, _k2, _pkey, 'INVEST', _ratio, _rtxt, 5, 1, 821))\n    for _p in _PE_BY.get(_sid, []):\n        _key = 'HPE%d_%d' % (_sid, _p[0])\n        _nodes.append(_gn(_tid, _key, 'Human', _p[2], None, 1, _center, '0', '0', '0',\n                          None, _grp, 1158, {'position': _p[6], 'ratioLabel': '任职'}))\n        _edges.append(_ge(_tid, _center, _key, 'SERVE_ALL', None, _p[6], 5, 3, 1158))\n    for _other, _rows in _SH_BY.items():\n        for _sh in _rows:\n            if _sh[2] == _sup['name']:\n                _key = 'C%d' % _other\n                if _key not in [n[2] for n in _nodes]:\n                    _nodes.append(_gn(_tid, _key, 'Company', _GEN_SUP[_other]['name'],\n                                      _GEN_SUP[_other]['credit'], 1, _center, '1', '0',\n                                      _GEN_SUP[_other]['monitor'], _other, _grp, 1160,\n                                      {'position': '被投资企业',\n                                       'ratioLabel': '%g%%' % round(_sh[7] * 100, 4)}))\n                _edges.append(_ge(_tid, _center, _key, 'INVEST', _sh[7],\n                                  '%g%%' % round(_sh[7] * 100, 4), 5, 1, 1160))\n    _GEN_TASKS.append(_gtask(_tid, 'MOCK-EQ-20261118-%03d' % (_tid - 1300), 'equity',\n                             'page5', _sid, len(_nodes), 12.00 + _sid % 10))\n    _GEN_NODES.extend(_nodes)\n    _GEN_EDGES.extend(_edges)\n\n# ---------- 页面6：幕后关系（同电话/同邮箱/共同董监高/参股/实际控制人） ----------\nfor _sid in sorted(_GEN_SUP):\n    _sup = _GEN_SUP[_sid]\n    _grp = 'GRP-%d' % _sid\n    _tid = 1400 + (_sid - 1000)\n    _nodes, _edges, _keys = [], [], set()\n    _center = 'C%d' % _sid\n\n    def _ensure_company(_node_sid, _level, _parent):\n        _k = 'C%d' % _node_sid\n        if _k in _keys:\n            return _k\n        _keys.add(_k)\n        _s2 = _GEN_SUP[_node_sid]\n        _nodes.append(_gn(_tid, _k, 'Company', _s2['name'], _s2['credit'], _level, _parent,\n                          '1', '0', _s2['monitor'], _node_sid, _grp, 1161,\n                          {'position': '中心企业' if _level == 0 else '关联方'}))\n        return _k\n\n    _keys.add(_center)\n    _nodes.append(_gn(_tid, _center, 'Company', _sup['name'], _sup['credit'], 0, None,\n                      '1', '0', _sup['monitor'], _sid, _grp, 1161, {'position': '中心企业'}))\n    for _v, _owners in _TEL_OWNER.items():\n        if _sid not in _owners or len(_owners) < 2:\n            continue\n        for _o in _owners:\n            if _o == _sid:\n                continue\n            _k = _ensure_company(_o, 1, _center)\n            _edges.append(_ge(_tid, _center, _k, 'ALL', None, '同电话 %s' % _v, 3, 4, 1156))\n    for _v, _owners in _MAIL_OWNER.items():\n        if _sid not in _owners or len(_owners) < 2:\n            continue\n        for _o in _owners:\n            if _o == _sid:\n                continue\n            _k = _ensure_company(_o, 1, _center)\n            _edges.append(_ge(_tid, _center, _k, 'ALL', None, '同邮箱', 3, 5, 1156))\n    _hcg = set(p[5] for p in _PE_BY.get(_sid, []) if p[5])\n    for _other, _rows in _PE_BY.items():\n        if _other == _sid:\n            continue\n        _share = [p for p in _rows if p[5] in _hcg]\n        if not _share:\n            continue\n        _k = _ensure_company(_other, 1, _center)\n        _edges.append(_ge(_tid, _center, _k, 'ALL', None,\n                          '共同董监高：%s' % '、'.join(p[2] for p in _share), 4, 7, 1156))\n    for _sh in _SH_BY.get(_sid, []):\n        if _sh[3] == '1' and _sh[2] in _GEN_BY_NAME:\n            _o = _GEN_BY_NAME[_sh[2]]\n            _k = _ensure_company(_o, 1, _center)\n            _edges.append(_ge(_tid, _k, _center, 'INVEST', _sh[7],\n                              '%g%%' % round(_sh[7] * 100, 4), 5, 1, 1160))\n    for _other, _rows in _SH_BY.items():\n        for _sh in _rows:\n            if _sh[2] == _sup['name']:\n                _k = _ensure_company(_other, 1, _center)\n                _edges.append(_ge(_tid, _center, _k, 'INVEST', _sh[7],\n                                  '%g%%' % round(_sh[7] * 100, 4), 5, 1, 1160))\n    _ctrl = None\n    for _j, _sh in enumerate(_SH_BY.get(_sid, []), start=1):\n        if _sh[3] != '2':\n            continue\n        _key = 'HBS%d_%d' % (_sid, _j)\n        if _ctrl is None or _sh[7] > _ctrl[1]:\n            _ctrl = (_key, _sh[7], _sh[2], _sh[6])\n        _nodes.append(_gn(_tid, _key, 'Human', _sh[2], None, 1, _center, '0', '0', '0',\n                          None, _grp, 1123, {'position': '自然人股东/疑似实际控制人',\n                                             'ratioLabel': '%g%%' % round(_sh[7] * 100, 4)}))\n        _edges.append(_ge(_tid, _key, _center, 'INVEST', _sh[7],\n                          '%g%%' % round(_sh[7] * 100, 4), 5, 1, 1123))\n    for _p in _PE_BY.get(_sid, []):\n        _key = 'HBS-PE%d_%d' % (_sid, _p[0])\n        _nodes.append(_gn(_tid, _key, 'Human', _p[2], None, 1, _center, '0',\n                          '1' if (_ctrl and _p[2] == _ctrl[2]) else '0', '0', None, _grp,\n                          1158, {'position': _p[6]}))\n        _edges.append(_ge(_tid, _center, _key, 'SERVE_ALL', None, _p[6], 4, 3, 1158))\n    _GEN_TASKS.append(_gtask(_tid, 'MOCK-BS-20261118-%03d' % (_tid - 1400), 'backstage',\n                             'page6', _sid, len(_nodes), 10.00 + _sid % 7))\n    _GEN_NODES.extend(_nodes)\n    _GEN_EDGES.extend(_edges)\n\n"

_AT = "table('srm_analysis_task', AT_COLS, TASKS)"
assert S.count(_AT) == 1, 'analysis task insert marker'
S = S.replace(_AT, BLOCK + "\n" + _AT, 1)

_GN = "table('srm_graph_node', GN_COLS, NODES + BNODES + B2NODES)"
assert S.count(_GN) == 1, 'graph node insert marker'
S = S.replace(_GN, "table('srm_graph_node', GN_COLS, NODES + BNODES + B2NODES + _GEN_NODES)", 1)

_GE = "table('srm_graph_edge', GE_COLS, EDGES + BEDGES + B2EDGES)"
assert S.count(_GE) == 1, 'graph edge insert marker'
S = S.replace(_GE, "table('srm_graph_edge', GE_COLS, EDGES + BEDGES + B2EDGES + _GEN_EDGES)", 1)


io.open(P, 'w', encoding='utf-8', newline='\n').write(S)
print('OK part2: 15 suppliers equity+backstage graph data generated')
